import json
from pathlib import Path
ROOT=Path(__file__).resolve().parent
ARMS=['brief','eager','on_demand']
NAMES={'brief':'Краткая запись','eager':'Правки сразу','on_demand':'Правки по запросу'}

def data(n):return json.loads((ROOT/n).read_text(encoding='utf8'))
def add_repair(w):
    g=data('grading/matched_groups.json')
    trials=g['trials']
    w.page('Интерактивный решатель   /   Официальные тесты','Помогают ли подробности при исправлении',
           'Четыре задачи Flask и Requests выбраны до открытия эталонных патчей по принадлежности репозиторию. Каждую решала локальная Qwen3.8-27B UD-Q4_K_M на RTX 3090. У каждого режима был один запуск на задачу и 24 модельных хода в изолированной копии официального образа.')
    w.p('Во всех трёх условиях решатель видел один и тот же исходный запрос, заранее выбранную историю, предыдущее описание и заключительную заметку. Менялся доступ к 40 словам о прошлой правке. В режиме по запросу модель могла явно открыть детали инструментом. Для Flask подходящего источника в зафиксированной десятке не оказалось. В трёх условиях Flask начальный текст и инструменты совпадали.')
    table=[]
    for a in ARMS:
        rs=[x for x in trials if x['arm']==a]
        table.append([NAMES[a],str(sum(x['resolved'] for x in rs))+'/4',str(sum(bool(x['patch_bytes']) for x in rs)),str(sum(x['calls'] for x in rs)),str(sum(x['read_requests'] for x in rs)),str(sum(x['input_tokens'] for x in rs))])
    w.tbl(['Режим','Решено','Патчей','Ходов','Запросов деталей','Входных токенов'],table,[3.8,2.1,2.0,2.0,3.4,3.8],True)
    w.p('Стоимость включает всю историю, заново переданную модели на каждом ходу, без кэширования промптов. Ходы включают вызовы shell и обычные ответы модели. Единица основного сравнения — запрос. При одинаковом весе каждого из трёх целевых PR доли решений составляют '+', '.join(NAMES[a].lower()+' '+f"{100*g['metrics'][a]['mean_within_pr_then_across_pr']:.1f}%" for a in ARMS)+'.')
    n=len(trials); empty=sum(not x['patch_bytes'] for x in trials); reached=sum(x['finish_reason']=='call_limit' for x in trials)
    w.p(f'В {reached} из {n} сеансов решатель исчерпал лимит ходов. В {empty} случаях он оставил пустой diff. Официальный оценщик отклоняет такие заявки до запуска тестов. На этом малом бюджете частота готовых исправлений ограничивает чувствительность сравнения представлений памяти. Повторных seed для оценки разброса не было.')
    w.source('Официальные образы, стенд и оценивание SWE-ContextBench','https://github.com/jiayuanz3/SWEContextBench/tree/12ad6ab14e18e9378e1e293c9edbc3f7ce43d27b')
    w.page('Контроль исполнения   /   По каждому назначению','Патч, тесты и происхождение результата',
           'Все назначения оценены на исходной версии отдельным экземпляром опубликованного оценщика. Эталон принят на четырёх формулировках. Инертный патч с новым текстовым файлом проверен тестами и отклонён на четырёх. Ещё четыре пустые контрольные заявки отклонены до тестов.')
    items=[]
    for target in sorted(set(x['instance_id'] for x in trials)):
        sub=sorted((x for x in trials if x['instance_id']==target),key=lambda x:ARMS.index(x['arm']))
        ro=[target.split('__')[-1]]
        for x in sub:
            status='Решена' if x['resolved'] else ('Пустой diff' if not x['patch_bytes'] else 'Не принята')
            ro.append(status+' · '+str(x['calls']))
        items.append(ro)
    w.tbl(['Задача','Краткая','Правки сразу','По запросу'],items,[4.2,4.25,4.25,4.4],True)
    w.p('Число после исхода — реальные модельные ходы. В архиве для каждого непустого патча сохранены SHA-256 и отчёт оценщика со статусами до и после. Независимый контроль передачи diff через интерфейс решателя успешно извлёк изменение существующего файла и новый файл. Процедура контролирует расхождение между результатом модели и поступившей на тесты заявкой.')
    w.p('В среде решателя отключена сеть, /testbed содержит один чистый commit с файлами базовой версии, команды выполняются пользователем с UID 1000. Проверочные патчи находятся у оценщика. Параметры генерации одинаковы в пределах задачи: температура 0,5, top-p 0,95, top-k 20, до 768 новых токенов на ответ. Режим внутреннего рассуждения выключен. Изменение длительности сессии, способа вызова инструментов или модели требует нового сравнения.')
    w.p('Сравнение с опубликованной REM возможно при воспроизведении её полного бюджета, основного решателя, протокола поиска и набора задач. Здесь мы проверяли более узкое вмешательство на четырёх формулировках. Даже одинаковые доли успеха в трёх условиях допускают практически важную разницу на большем наборе.')
    w.source('REM, постановка и параметры сравнений','https://arxiv.org/abs/2610.27377')

